CREATE OR REPLACE PROCEDURE sp(para_enr NUMBER, para_pID NUMBER, para_cName VARCHAR2, para_yCard VARCHAR2) IS
 CURSOR ref_cursor1 IS SELECT * FROM "College" WHERE "enr" = para_enr FOR UPDATE;
 CURSOR ref_cursor2 IS SELECT * FROM "Tryout" WHERE "pID" > para_pID FOR UPDATE;
 rec1 ref_cursor1%ROWTYPE;
 rec2 ref_cursor2%ROWTYPE;
 counter INTEGER := 0;
 new_pID NUMBER;
 max_tryout_pID NUMBER := 0;
BEGIN
 OPEN ref_cursor1;
 LOOP
  FETCH ref_cursor1 INTO rec1;
  EXIT WHEN ref_cursor1%NOTFOUND;
  DELETE FROM "College" WHERE CURRENT OF ref_cursor1;
 END LOOP;
 CLOSE ref_cursor1;
 OPEN ref_cursor2;
 LOOP
  FETCH ref_cursor2 INTO rec2;
  EXIT WHEN ref_cursor2%NOTFOUND;
  UPDATE "Tryout" SET "cName" = {SLOT_1} WHERE CURRENT OF ref_cursor2;
  counter := {SLOT_2};
  IF {SLOT_3} THEN
   max_tryout_pID := {SLOT_4};
  END IF;
 END LOOP;
 CLOSE ref_cursor2;
 IF {SLOT_5} THEN
  SELECT GREATEST(NVL(MAX("pID"), 0), max_tryout_pID) + 1 INTO new_pID FROM "Player";
  INSERT INTO "Player" ("pID", "yCard") VALUES (new_pID, para_yCard);
 END IF;
END;

